        archive.writestr(info, (lib / pathlib.PurePosixPath(name)).read_bytes())
"#;
    let status = Command::new(python_root.join("python.exe"))
        .args([OsStr::new("-I"), OsStr::new("-c"), OsStr::new(code)])
        .arg(&output)
        .arg(python_root.join("Lib"))
        .status()
        .unwrap();
    assert!(status.success());
    assert!(output.is_file());
